initJs:
function(container, apiUrl, tables) {
  const tbody = container.querySelector("#inventory-tbody");
  const resultCount = container.querySelector("#result-count");
  const noResults = container.querySelector("#no-results");
  const errorMessage = container.querySelector("#error-message");

  // 店舗マスタのインデックスを取得
  const storeTableIndex = tables.findIndex(t => t.tableName === "店舗マスタ");
  const productTableIndex = tables.findIndex(t => t.tableName === "商品マスタ");

  // 店舗選択肢を初期化
  function initStoreOptions() {
    const storeSelect = container.querySelector("#store-select");
    if (storeTableIndex >= 0 && tables[storeTableIndex].records) {
      tables[storeTableIndex].records.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement("option");
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // エラーメッセージ表示
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove("hidden");
    setTimeout(() => {
      errorMessage.classList.add("hidden");
    }, 5000);
  }

  // 在庫状況を判定
  function getStockStatus(currentStock, safetyStock) {
    if (!safetyStock) return "適正";
    const ratio = currentStock / safetyStock;
    if (ratio < 0.5) return "不足";
    if (ratio > 2.0) return "過剰";
    return "適正";
  }

  // 在庫状況のスタイルを取得
  function getStatusStyle(status) {
    switch (status) {
      case "不足":
        return "background: rgba(255, 106, 0, 0.1); color: #ff6a00; padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 500;";
      case "過剰":
        return "background: rgba(255, 193, 7, 0.1); color: #ffc107; padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 500;";
      default:
        return "background: rgba(40, 167, 69, 0.1); color: #28a745; padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 500;";
    }
  }

  // 在庫データを生成（デモ用）
  function generateInventoryData(products, storeId) {
    if (!products || !storeId) return [];

    return products.filter(p => p.有効フラグ).map(product => {
      const currentStock = Math.floor(Math.random() * 200);
      const safetyStock = Math.floor(Math.random() * 50) + 10;
      const orderPoint = Math.floor(safetyStock * 1.5);
      const lastReceived = new Date(Date.now() - Math.floor(Math.random() * 30) * 24 * 60 * 60 * 1000);

      return {
        id: `${storeId}-${product.商品ID}`,
        商品コード: product.商品コード,
        商品名: product.商品名,
        現在在庫数: currentStock,
        安全在庫数: safetyStock,
        発注点: orderPoint,
        最終入荷日: lastReceived.toISOString().split('T')[0],
        在庫状況: getStockStatus(currentStock, safetyStock),
        商品カテゴリ: product.商品カテゴリID // カテゴリフィルタ用
      };
    });
  }

  // テーブル再描画関数
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = "";
      resultCount.textContent = "0件";
      noResults.classList.remove("hidden");
      return;
    }

    noResults.classList.add("hidden");
    resultCount.textContent = `${rows.length}件`;

    tbody.innerHTML = rows.map(row => `
      <tr data-id="${row.id}">
        <td>${row.商品コード || ""}</td>
        <td>${row.商品名 || ""}</td>
        <td style="text-align: right;">${row.現在在庫数 || 0}</td>
        <td style="text-align: right;">${row.安全在庫数 || 0}</td>
        <td style="text-align: right;">${row.発注点 || 0}</td>
        <td>${row.最終入荷日 || ""}</td>
        <td><span style="${getStatusStyle(row.在庫状況)}">${row.在庫状況}</span></td>
      </tr>
    `).join("");
  }

  // 検索処理
  async function performSearch() {
    const storeId = container.querySelector("#store-select").value;
    const category = container.querySelector("#category-select").value;
    const productName = container.querySelector("#product-name-search").value.trim();
    const productCode = container.querySelector("#product-code-search").value.trim();
    const stockStatus = container.querySelector("#stock-status-filter").value;

    // バリデーション
    if (!storeId) {
      showError("店舗を選択してください。");
      return;
    }

    // 特殊文字チェック
    const dangerousChars = /<script|javascript:|on\w+\s*=|['";]|DROP\s+TABLE|SELECT\s+\*|INSERT\s+INTO|DELETE\s+FROM/i;
    if (dangerousChars.test(productName) || dangerousChars.test(productCode)) {
      showError("不正な文字が含まれています。");
      return;
    }

    // 商品コード形式チェック（英数字とハイフンのみ、最大20文字）
    if (productCode && !/^[A-Za-z0-9\-]{1,20}$/.test(productCode)) {
      showError("商品コードは英数字とハイフン、最大20文字で入力してください。");
      return;
    }

    try {
      // 商品マスタを取得
      const products = await window.aivicApi.list(productTableIndex);
      if (!products) {
        showError("商品データの取得に失敗しました。");
        return;
      }

      // 在庫データを生成
      let inventoryData = generateInventoryData(products, storeId);

      // フィルタリング
      if (category) {
        inventoryData = inventoryData.filter(item => {
          const product = products.find(p => p.商品コード === item.商品コード);
          return product && product.商品カテゴリID === category;
        });
      }

      if (productName) {
        inventoryData = inventoryData.filter(item => 
          item.商品名.toLowerCase().includes(productName.toLowerCase())
        );
      }

      if (productCode) {
        inventoryData = inventoryData.filter(item => 
          item.商品コード.toLowerCase().includes(productCode.toLowerCase())
        );
      }

      if (stockStatus) {
        inventoryData = inventoryData.filter(item => item.在庫状況 === stockStatus);
      }

      renderRows(inventoryData);

    } catch (error) {
      showError("検索処理中にエラーが発生しました。");
      console.error("Search error:", error);
    }
  }

  // CSVエクスポート
  function exportCSV() {
    const storeId = container.querySelector("#store-select").value;
    if (!storeId) {
      showError("店舗を選択してからエクスポートしてください。");
      return;
    }

    window.aivicApi.list(productTableIndex).then(products => {
      if (!products) return;

      const inventoryData = generateInventoryData(products, storeId);

      const headers = ["商品コード", "商品名", "現在在庫数", "安全在庫数", "発注点", "最終入荷日", "在庫状況"];
      const csvContent = [
        headers.join(","),
        ...inventoryData.map(row => [
          `"${row.商品コード || ""}"`,
          `"${row.商品名 || ""}"`,
          row.現在在庫数 || 0,
          row.安全在庫数 || 0,
          row.発注点 || 0,
          `"${row.最終入荷日 || ""}"`,
          `"${row.在庫状況 || ""}"`
        ].join(","))
      ].join("\n");

      const blob = new Blob(["\uFEFF" + csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = `inventory_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    });
  }

  // 検索条件クリア
  function clearSearchConditions() {
    container.querySelector("#store-select").value = "";
    container.querySelector("#category-select").value = "";
    container.querySelector("#product-name-search").value = "";
    container.querySelector("#product-code-search").value = "";
    container.querySelector("#stock-status-filter").value = "";
    renderRows([]);
  }

  // 初期化
  initStoreOptions();
  renderRows([]);

  // イベントリスナー
  container.querySelector("#btn-search").addEventListener("click", performSearch);
  container.querySelector("#btn-clear").addEventListener("click", clearSearchConditions);
  container.querySelector("#btn-export").addEventListener("click", exportCSV);

  // Enterキーで検索
  container.querySelector("#product-name-search").addEventListener("keypress", (e) => {
    if (e.key === "Enter") performSearch();
  });

  container.querySelector("#product-code-search").addEventListener("keypress", (e) => {
    if (e.key === "Enter") performSearch();
  });
}
